<?php
session_start();if(($_SESSION['role']??'')!=='admin'){header('Location: /authenication/login/login.php');exit;}require_once(__DIR__.'/../../../Database/db/db.php');$pdo=get_db();$start=$_GET['start']??date('Y-m-01');$end=$_GET['end']??date('Y-m-d');foreach(['start','end'] as $key){if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',${$key})){${$key}=$key==='start'?date('Y-m-01'):date('Y-m-d');}}$q=$pdo->prepare('SELECT COUNT(*) total,COALESCE(AVG(progress),0) average_progress,SUM(status="completed") completed,SUM(status="active") active FROM enrollments WHERE DATE(created_at) BETWEEN ? AND ?');$q->execute([$start,$end]);$summary=$q->fetch(PDO::FETCH_ASSOC);$q=$pdo->prepare('SELECT c.id,c.title,COUNT(e.id) enrollments,COALESCE(AVG(e.progress),0) average_progress,SUM(e.status="completed") completed FROM courses c LEFT JOIN enrollments e ON e.course_id=c.id AND DATE(e.created_at) BETWEEN ? AND ? GROUP BY c.id,c.title ORDER BY enrollments DESC,c.title LIMIT 100');$q->execute([$start,$end]);$courses=$q->fetchAll(PDO::FETCH_ASSOC);$pageTitle='Performance metrics';include(__DIR__.'/../../includes/header/header.php');include(__DIR__.'/../../includes/navbar/navbar.php');include(__DIR__.'/../../includes/sidebar/sidebar.php');
?>
<main class="main-content"><div class="container-fluid"><div class="page-heading"><div><span class="page-kicker">REPORTS</span><h1>Performance metrics</h1><p>Course progress and enrollment outcomes for the selected enrollment period.</p></div></div><section class="card border-0 mb-4"><div class="card-body"><form class="row g-3 align-items-end" method="get"><div class="col-sm-4"><label class="form-label">From</label><input class="form-control" type="date" name="start" value="<?=htmlspecialchars($start)?>"></div><div class="col-sm-4"><label class="form-label">Through</label><input class="form-control" type="date" name="end" value="<?=htmlspecialchars($end)?>"></div><div class="col-sm-4"><button class="btn btn-primary">Apply dates</button><a class="btn btn-light ms-2" href="?">This month</a></div></form></div></section><div class="row g-3 mb-4"><div class="col-sm-4"><div class="metric-card"><span class="metric-icon purple"><i class="fa-solid fa-chart-line"></i></span><span class="metric-label">Average progress</span><strong><?=number_format((float)$summary['average_progress'],1)?>%</strong><small>Across selected enrollments</small></div></div><div class="col-sm-4"><div class="metric-card"><span class="metric-icon blue"><i class="fa-solid fa-users"></i></span><span class="metric-label">Enrollments</span><strong><?=number_format((int)$summary['total'])?></strong><small>In the selected period</small></div></div><div class="col-sm-4"><div class="metric-card"><span class="metric-icon green"><i class="fa-solid fa-circle-check"></i></span><span class="metric-label">Completed</span><strong><?=number_format((int)$summary['completed'])?></strong><small><?=number_format((int)$summary['active'])?> active enrollments</small></div></div></div><section class="card border-0"><div class="table-toolbar"><div><h2 class="h5 mb-1">Course performance</h2></div><div class="table-search"><i class="fa-solid fa-magnifying-glass"></i><input data-table-search="performanceTable" placeholder="Search courses" aria-label="Search courses"></div></div><div class="table-responsive"><table class="table admin-table mb-0" id="performanceTable" data-admin-sort><thead><tr><th data-sort>Course</th><th data-sort>Enrollments</th><th data-sort>Average progress</th><th data-sort>Completed</th></tr></thead><tbody><?php if(!$courses):?><tr><td colspan="4"><div class="empty-state"><strong>No course activity for this period</strong></div></td></tr><?php endif;?><?php foreach($courses as $course):?><tr><td><?=htmlspecialchars($course['title'],ENT_QUOTES,'UTF-8')?></td><td><?=number_format((int)$course['enrollments'])?></td><td><?=number_format((float)$course['average_progress'],1)?>%</td><td><?=number_format((int)$course['completed'])?></td></tr><?php endforeach;?></tbody></table></div></section></div></main><?php include(__DIR__.'/../../includes/footer/footer.php');?>
